O("n1637298789", "פסל פרדיננד דומלה ניוונהאוס", "Statue of Ferdinand Domela Nieuwenhuis", 52.385273, 4.881777, "פסל", ["ppl", "h3"],
  "פסל ברונזה של פרדיננד דומלה ניוונהאוס, ממייסדי התנועה הסוציאליסטית בהולנד, מעשה ידיו של יוהאן פולט מ-1931. הדמות עומדת בכיכר נאסאופליין, קרוב לשער וילם, ולפי המסופר משמשת מקום התכנסות לאירועים של תנועת הפועלים.",
  "בכיכר נאסאופליין, כ-150 מטרים מהארלמרפליין ומשער וילם, בקצה המערבי של רחוב הארלמרדייק, ליד המעבר אל הארלמרווח.",
  "פרדיננד דומלה ניוונהאוס (1846-1919) היה בתחילת דרכו כומר לותרני, ובשנות ה-70 של המאה ה-19 עזב את הכנסייה והצטרף לתנועת הפועלים. הוא נבחר ב-1888 לפרלמנט ההולנדי, הנציג הסוציאליסטי הראשון בו, ובשנים שאחר כך פנה לעמדות אנרכיסטיות והתרחק מהפעילות הפרלמנטרית. בקרב תומכיו הוא כונה 'אבא דומלה' ונחשב לדמות אהודה בקרב פועלים בהולנד.\nהפסל הוצב ב-1931, יותר מעשור אחרי מותו, לפי המסופר במימון תרומות של תומכיו. לפי המקובל, הפסל יוהאן פולט עיצב את הדמות בצורה מוארכת ומסוגננת, בהשפעת זרמי הפיסול המודרני של התקופה, ולא כדיוקן ריאליסטי. בוויקיפדיה ההולנדית יש ערך על הפסל.",
  "לפי OSM הפסל עשוי ברונזה. הכיכר נאסאופליין נמצאת בנקודה שבה העיר הישנה פוגשת את רובע וסט, ומשם אפשר להמשיך אל וסטרפארק ואל מתחם וסטרגאסורק. ההארלמרפליין הסמוך, עם שער וילם הניאו־קלאסי, הוא אחת הכיכרות הנעימות בצפון־מערב מרכז העיר, ובקרבתו עומד גם הפסל של יאקוב ואן לנפ מ-2016.",
  ["הפסל של יוהאן פולט הוצב ב-1931.", "דומלה ניוונהאוס נבחר ב-1888 לפרלמנט, הנציג הסוציאליסטי הראשון בו."],
  "משלבים עם שער וילם ועם פסל יאקוב ואן לנפ הסמוך, וממשיכים לאורך הארלמרסטראט אל הירדן.", w=1, yr="1931", by="יוהאן פולט", s=7.4, b=1),

O("n7397368926", "אבן הזיכרון לבית המעצר לשעבר", "Memorial stone for the former Huis van Bewaring", 52.362838, 4.883253, "לוח זיכרון עם תבליט", ["h2"],
  "אבן זיכרון של הפסל פיטר זאנן מ-1992, במקום שבו עמד בית המעצר (Huis van Bewaring) של אמסטרדם ברחוב ותרינחסחאנס. בתקופת הכיבוש הגרמני הוחזקו בו אנשי מחתרת, יהודים ואסירים פוליטיים, והאבן מזכירה את מי שעברו בו.",
  "בצד הדרומי של ותרינחסחאנס, כ-90 מטרים מפרדיסו, בקרבת כיכר מקס אויווה ולייצפליין.",
  "בית המעצר ברחוב ותרינחסחאנס היה בית כלא עירוני מהמאה ה-19. בזמן הכיבוש הגרמני של הולנד, בין 1940 ל-1945, השתמשו בו השלטונות הגרמניים גם כמקום מעצר לאנשי ההתנגדות, ליהודים שנעצרו ולאסירים פוליטיים, שחלקם הועברו משם למחנות. ב-1 במאי 1944 ניסתה קבוצת מחתרת, בהנהגת הפסל ואיש ההתנגדות חריט ואן דר וין, לפרוץ לבניין ולשחרר אסירים. הניסיון נכשל, ואן דר וין נפצע ונתפס, ובהמשך הוצא להורג.\nאחרי המלחמה נהרס הבניין, ובמקום נבנו מאוחר יותר מבנים חדשים, ככל הנראה המתחם שסביב כיכר מקס אויווה. אבן הזיכרון הוצבה ב-1992, ולפי OSM יצר אותה פיטר זאנן. היא רשומה גם במאגר אנדרטאות המלחמה של הוועדה הלאומית ל-4 ול-5 במאי.",
  "לפי OSM האבן עשויה אבן והיא מסומנת כאנדרטה לכלא לשעבר. בוויקיפדיה ההולנדית יש ערך בשם 'אבן הזיכרון לבית המעצר לשעבר'. ב-4 במאי, יום הזיכרון ההולנדי לחללי המלחמה, מניחים לעתים פרחים באנדרטאות כמו זו. מבנה הכלא עמד בצד הצפוני של הסינגלחראכט, ומעבר לתעלה, כמה דקות הליכה דרומה, נמצאים הרייקסמוזיאום והמוזיאונפליין.",
  ["האבן של פיטר זאנן הוצבה ב-1992.", "ב-1 במאי 1944 נכשל ניסיון מחתרתי לשחרר אסירים מהבניין."],
  "עוצרים לכמה רגעים בדרך מלייצפליין לפרדיסו, ובמאי אפשר לראות כאן פרחים מטקסי הזיכרון.", w=1, yr="1992", by="פיטר זאנן", s=6.8, b=1),

